        $this->rolPrivilegiosScheduledForDeletion = $rolPrivilegiosToDelete;

        foreach ($rolPrivilegiosToDelete as $rolPrivilegioRemoved) {
            $rolPrivilegioRemoved->setForma(null);
        }

        $this->collRolPrivilegios = null;
        foreach ($rolPrivilegios as $rolPrivilegio) {
            $this->addRolPrivilegio($rolPrivilegio);
        }

        $this->collRolPrivilegios = $rolPrivilegios;
        $this->collRolPrivilegiosPartial = false;

        return $this;
    }

    /**
     * Returns the number of related RolPrivilegio objects.
     *
     * @param Criteria $criteria
     * @param boolean $distinct
     * @param PropelPDO $con
     * @return int             Count of related RolPrivilegio objects.
     * @throws PropelException
     */
    public function countRolPrivilegios(Criteria $criteria = null, $distinct = false, PropelPDO $con = null)
    {
        $partial = $this->collRolPrivilegiosPartial && !$this->isNew();
        if (null === $this->collRolPrivilegios || null !== $criteria || $partial) {
            if ($this->isNew() && null === $this->collRolPrivilegios) {
                return 0;
            }

            if ($partial && !$criteria) {
                return count($this->getRolPrivilegios());
            }
            $query = RolPrivilegioQuery::create(null, $criteria);
            if ($distinct) {
                $query->distinct();
            }

            return $query
                ->filterByForma($this)
                ->count($con);
        }

        return count($this->collRolPrivilegios);
    }

    /**
     * Method called to associate a RolPrivilegio object to this object
     * through the RolPrivilegio foreign key attribute.
     *
     * @param    RolPrivilegio $l RolPrivilegio
     * @return Forma The current object (for fluent API support)
     */
    public function addRolPrivilegio(RolPrivilegio $l)
    {
        if ($this->collRolPrivilegios === null) {
            $this->initRolPrivilegios();
            $this->collRolPrivilegiosPartial = true;
        }

        if (!in_array($l, $this->collRolPrivilegios->getArrayCopy(), true)) { // only add it if the **same** object is not already associated
            $this->doAddRolPrivilegio($l);

            if ($this->rolPrivilegiosScheduledForDeletion and $this->rolPrivilegiosScheduledForDeletion->contains($l)) {
                $this->rolPrivilegiosScheduledForDeletion->remove($this->rolPrivilegiosScheduledForDeletion->search($l));
            }
        }

        return $this;
    }

    /**
     * @param	RolPrivilegio $rolPrivilegio The rolPrivilegio object to add.
     */
    protected function doAddRolPrivilegio($rolPrivilegio)
    {
        $this->collRolPrivilegios[]= $rolPrivilegio;
        $rolPrivilegio->setForma($this);
    }

    /**
     * @param	RolPrivilegio $rolPrivilegio The rolPrivilegio object to remove.
     * @return Forma The current object (for fluent API support)
     */
    public function removeRolPrivilegio($rolPrivilegio)
    {
        if ($this->getRolPrivilegios()->contains($rolPrivilegio)) {
            $this->collRolPrivilegios->remove($this->collRolPrivilegios->search($rolPrivilegio));
            if (null === $this->rolPrivilegiosScheduledForDeletion) {
                $this->rolPrivilegiosScheduledForDeletion = clone $this->collRolPrivilegios;
                $this->rolPrivilegiosScheduledForDeletion->clear();
            }
            $this->rolPrivilegiosScheduledForDeletion[]= clone $rolPrivilegio;
            $rolPrivilegio->setForma(null);
        }

        return $this;
    }


    /**
     * If this collection has already been initialized with
     * an identical criteria, it returns the collection.
     * Otherwise if this Forma is new, it will return
     * an empty collection; or if this Forma has previously
     * been saved, it will retrieve related RolPrivilegios from storage.
     *
     * This method is protected by default in order to keep the public
     * api reasonable.  You can provide public methods for those you
     * actually need in Forma.
     *
     * @param Criteria $criteria optional Criteria object to narrow the query
     * @param PropelPDO $con optional connection object
     * @param string $join_behavior optional join type to use (defaults to Criteria::LEFT_JOIN)
     * @return PropelObjectCollection|RolPrivilegio[] List of RolPrivilegio objects
     */
    public function getRolPrivilegiosJoinRol($criteria = null, $con = null, $join_behavior = Criteria::LEFT_JOIN)
    {
        $query = RolPrivilegioQuery::create(null, $criteria);
        $query->joinWith('Rol', $join_behavior);

        return $this->getRolPrivilegios($query, $con);
    }

    /**
     * Clears the current object and sets all attributes to their default values
     */
    public function clear()
    {
        $this->forma_id = null;
        $this->modulo_id = null;
        $this->nombre = null;
        $this->descripcion = null;
        $this->ruta = null;
        $this->is_public = null;
        $this->alreadyInSave = false;
        $this->alreadyInValidation = false;
        $this->alreadyInClearAllReferencesDeep = false;
        $this->clearAllReferences();
        $this->resetModified();
        $this->setNew(true);
        $this->setDeleted(false);
    }

    /**
     * Resets all references to other model objects or collections of model objects.
     *
     * This method is a user-space workaround for PHP's inability to garbage collect
     * objects with circular references (even in PHP 5.3). This is currently necessary
     * when using Propel in certain daemon or large-volume/high-memory operations.
     *
     * @param boolean $deep Whether to also clear the references on all referrer objects.
     */
    public function clearAllReferences($deep = false)
    {
        if ($deep && !$this->alreadyInClearAllReferencesDeep) {
            $this->alreadyInClearAllReferencesDeep = true;
            if ($this->collUsuarioPrivilegios) {
                foreach ($this->collUsuarioPrivilegios as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collRolPrivilegios) {
                foreach ($this->collRolPrivilegios as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->aModulo instanceof Persistent) {
              $this->aModulo->clearAllReferences($deep);
            }

            $this->alreadyInClearAllReferencesDeep = false;
        } // if ($deep)

        if ($this->collUsuarioPrivilegios instanceof PropelCollection) {
            $this->collUsuarioPrivilegios->clearIterator();
        }
        $this->collUsuarioPrivilegios = null;
        if ($this->collRolPrivilegios instanceof PropelCollection) {
            $this->collRolPrivilegios->clearIterator();
        }
        $this->collRolPrivilegios = null;
        $this->aModulo = null;
    }

    /**
     * return the string representation of this object
     *
     * @return string
     */
    public function __toString()
    {
        return (string) $this->exportTo(FormaPeer::DEFAULT_STRING_FORMAT);
    }

    /**
     * return true is the object is in saving state
     *
     * @return boolean
     */
    public function isAlreadyInSave()
    {
        return $this->alreadyInSave;
    }

    /**
     * Catches calls to virtual methods
     */
    public function __call($name, $params)
    {
        
        // symfony_behaviors behavior
        if ($callable = sfMixer::getCallable('BaseForma:' . $name))
        {
          array_unshift($params, $this);
          return call_user_func_array($callable, $params);
        }


        return parent::__call($name, $params);
    }

